import React from "react";
import "./BudgetLimits.css";

function BudgetLimits({
  budgetLimits = {},
  setBudgetLimits,
  onNext
}) {

  // ✅ fallback safety
  const safeLimits = budgetLimits || {};

  const handleChange = (category, value) => {
    if (typeof setBudgetLimits !== "function") return; // ✅ prevent crash

    setBudgetLimits({
      ...safeLimits,
      [category]: value
    });
  };

  return (
    <div className="spending-container">
      
      <h1 className="spending-title">
        Set Monthly Limits for Major Expenses
      </h1>

      <div className="spending-grid">

        <div className="spending-card active">
          <h3>Food & Groceries</h3>
          <input
            type="number"
            className="limit-input"
            placeholder="Enter amount"
            value={safeLimits["Food & Groceries"] || ""}
            onChange={(e) =>
              handleChange("Food & Groceries", e.target.value)
            }
          />
        </div>

        <div className="spending-card active">
          <h3>Bills</h3>
          <input
            type="number"
            className="limit-input"
            placeholder="Enter amount"
            value={safeLimits["Bills"] || ""}
            onChange={(e) =>
              handleChange("Bills", e.target.value)
            }
          />
        </div>

        <div className="spending-card active">
          <h3>Shopping</h3>
          <input
            type="number"
            className="limit-input"
            placeholder="Enter amount"
            value={safeLimits["Shopping"] || ""}
            onChange={(e) =>
              handleChange("Shopping", e.target.value)
            }
          />
        </div>

        <div className="spending-card active">
          <h3>Transport</h3>
          <input
            type="number"
            className="limit-input"
            placeholder="Enter amount"
            value={safeLimits["Transport"] || ""}
            onChange={(e) =>
              handleChange("Transport", e.target.value)
            }
          />
        </div>

      </div>

      <button
        className="spending-button"
        onClick={() => onNext(safeLimits)}
      >
        Save Limits
      </button>

    </div>
  );
}

export default BudgetLimits;
